select * from [dbo].[customer]

-- Q1. What is the total revenue generated by male vs. female customers?
select gender,sum(purchase_amount) [Revenue Generated] from customer
group by gender

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
select customer_id,purchase_amount from customer
where discount_applied='yes' and purchase_amount>=(select avg(purchase_amount) from customer)

-- Q3. Which are the top 5 products with the highest average review rating?
select Top 5 item_purchased,Round(avg(review_rating),2) as "Avg Review" from customer 
group by item_purchased 
order by avg(review_rating) desc
-- Products with higher rating can be higlighted in marketing campaigns and the prices of them can be increased as well
-- so as to sell them at higher profits


-- Q4. Compare the average purchase amounts between Standard and Express Shipping.
select shipping_type,Round(avg(purchase_amount),2) as "Average Price Amount" from customer
where shipping_type in ('Standard','Express')
group by shipping_type

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

select subscription_status,
count(*) as "Total Customers",
Round(avg(purchase_amount),2) as "Average_Spend",
Round(sum(purchase_amount),2) as "Total_Revenue" 
from customer 
group by subscription_status
order by Average_spend,Total_Revenue Desc

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select * from customer

select top 5 item_purchased,
CAST(ROUND(100.0*
		sum(CASE WHEN discount_applied='yes' THEN 1 ELSE 0 END)/count(*),
		2) as DECIMAL(10,2))
			as "percentage_purchase" 
	from customer
group by item_purchased
order by percentage_purchase desc


-- to remove the integer division error, .0 is attached to the end

-- Q7. Segment customers into New, 
-- Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.

-- The CTE provides a way to create a table from our own queries and then apply queries on that table
-- here 'customers_segment' is the table_name and 'segment' is the column name

with customers_segment as 
(SELECT
CASE 
	WHEN previous_purchases=1 THEN 'New'
	WHEN previous_purchases BETWEEN 2 and 10 THEN 'Returning'
	ELSE 'Loyal' END AS segment
	from customer
)
SELECT segment,count(*) as 'Total_customers'
from customers_segment
group by segment




-- Q8. What are the top 3 most purchased products within each category?
WITH total_purchase as
(
SELECT category,item_purchased,count(*) as 'sum_purchases',ROW_NUMBER() OVER(PARTITION BY category ORDER BY count(*) desc) as 'rank_no'
from customer
group by item_purchased,category
)
SELECT category,item_purchased,sum_purchases,rank_no
from total_purchase
where rank_no<=3

-- Q9. Are the customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?


WITH prob as 
(
SELECT subscription_status
from customer
where previous_purchases>5
)
SELECT subscription_status,CAST(ROUND((100.0*count(*)/(select count(*) from prob)),2) as DECIMAL(10,2)) 
	as 'percentage'
	from prob
	group by subscription_status

	 
-- select count(*) from prob --> provides total no. of repeat buyers with previous_pur>5

-- Q10. What is the revenue contribution of each age group?
SELECT * from customer

SELECT age_group,sum(purchase_amount) as 'total_revenue' from customer
group by age_group
order by total_revenue desc
